function incompleteGrades() {
  const missing = [];
  roomData.students.forEach(s => {
    roomData.subjects.forEach(subject => {
      if ((values.get(keyOf(s.student_code, subject.subject_code)) ?? "") === "") {
        missing.push(`${s.student_code} / ${subject.subject_name}`);
      }
    });
  });
  return missing;
}

